export function label(value) { return value + '!' }
import React from 'react'
import { label } from './helper.js'
type Props = { active: boolean }
export function Multiline({ active }: Props) {
  return <section>
      {active &&
        <span data-kind="active">
          {label('active')}
        </span>
      }
      <em>{label('tail')}</em>
    </section>
}
